begin;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000071','community-71@example.invalid'),('00000000-0000-4000-8000-000000000072','community-72@example.invalid'),('00000000-0000-4000-8000-000000000073','community-73@example.invalid'),('00000000-0000-4000-8000-000000000074','community-74@example.invalid');
do $$declare u uuid:='00000000-0000-4000-8000-000000000071';v uuid:='00000000-0000-4000-8000-000000000072';w uuid:='00000000-0000-4000-8000-000000000073';outsider uuid:='00000000-0000-4000-8000-000000000074';p uuid;flat uuid;post uuid;ride uuid;rid uuid;rid2 uuid;item uuid;conv uuid;home uuid;hi uuid;res jsonb;body jsonb;bad boolean;media uuid;
begin
 select id into p from public.projects order by name limit 1;
 insert into public.flats(project_id,label) values(p,'99996') returning id into flat;
 insert into public.memberships(user_id,flat_id,kind,status) values(u,flat,'owner','approved'),(v,flat,'tenant','approved'),(w,flat,'household','approved');
