 perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.community_api('my-profile','POST',jsonb_build_object('name','TEST resident A','bio','private bio','occupation','Engineer','contact','1234567890','contactVisibility','friends','locked',true,'discoverable',true,'networkVisible',true));
 post:=(public.community_api('social-posts','POST','{"body":"TEST community post","visibility":"project"}')->>'id')::uuid;
 media:=public.community_media_add('image/png','iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y9ZfGAAAAAASUVORK5CYII=');
 perform public.community_api('my-profile','POST',jsonb_build_object('name','TEST resident A','bio','private bio','occupation','Engineer','contact','1234567890','contactVisibility','friends','locked',true,'discoverable',true,'networkVisible',true,'avatar',media::text));
 perform set_config('request.jwt.claim.sub',v::text,true);
 res:=public.community_api('profiles/'||u);if res->>'bio'<>'' or res->>'contact'<>'' or res->>'avatar'<>'' or res->>'flat'<>'' or jsonb_array_length(res->'posts')<>0 then raise exception 'Locked profile leaked';end if;
 bad:=false;begin perform public.community_media_get(media);exception when others then bad:=true;end;if not bad then raise exception 'Locked photo leaked';end if;
 perform public.community_api('friends/'||u,'POST','{"action":"request"}');
