 perform set_config('request.jwt.claim.sub',u::text,true);perform public.community_api('friends/'||v,'POST','{"action":"accept"}');
 perform set_config('request.jwt.claim.sub',v::text,true);res:=public.community_api('profiles/'||u);if res->>'bio'<>'private bio' or res->>'contact'<>'1234567890' or jsonb_array_length(res->'posts')<>1 then raise exception 'Accepted profile projection failed';end if;perform public.community_media_get(media);
 perform public.community_api('social-posts/'||post,'POST','{"action":"like"}');perform public.community_api('social-posts/'||post,'POST','{"action":"comment","body":"TEST reply"}');
 res:=public.community_api('community');if jsonb_array_length(res->'social'->'feed')<>1 or res->'social'->'feed'->0->>'likes'<>'1' then raise exception 'Feed interaction failed';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 ride:=(public.community_api('rides','POST',jsonb_build_object('pickup','TEST entrance','destination','TEST office','departure',now()+interval '1 day','seats',1))->>'id')::uuid;
 perform public.community_api('rides/'||ride,'PATCH','{"action":"share_contact","contact":"1234567890"}');
 perform set_config('request.jwt.claim.sub',v::text,true);perform public.community_api('rides/'||ride,'PATCH','{"action":"request"}');select id into rid from public.ride_requests where ride_id=ride and user_id=v;
 res:=public.community_api('rides');if res->0->>'contact'<>'' then raise exception 'Pre-acceptance phone leak';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);perform public.community_api('rides/'||ride,'PATCH','{"action":"request"}');select id into rid2 from public.ride_requests where ride_id=ride and user_id=w;
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.community_api('rides/'||ride,'PATCH',jsonb_build_object('action','accept','requestId',rid));perform public.community_api('rides/'||ride,'PATCH',jsonb_build_object('action','accept','requestId',rid));
 if (select seats from public.rides where id=ride)<>0 then raise exception 'Seat replay failed';end if;
 bad:=false;begin perform public.community_api('rides/'||ride,'PATCH',jsonb_build_object('action','accept','requestId',rid2));exception when others then bad:=true;end;if not bad then raise exception 'Overbooking accepted';end if;
 perform set_config('request.jwt.claim.sub',v::text,true);res:=public.community_api('rides');if res->0->>'contact'<>'1234567890' then raise exception 'Accepted contact missing';end if;perform public.community_api('rides/'||ride,'PATCH','{"action":"withdraw"}');perform public.community_api('rides/'||ride,'PATCH','{"action":"withdraw"}');
 if (select seats from public.rides where id=ride)<>1 or public.community_api('rides')->0->>'contact'<>'' then raise exception 'Withdraw replay/contact revoke failed';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 body:=jsonb_build_object('projectId',p,'title','TEST chair','description','TEST private listing','category','Furniture','condition','Good','type','sale','price',50000,'audience','project','status','active','photos',jsonb_build_array(media::text),'key',gen_random_uuid());
 item:=(public.community_api('exchange','POST',body)->>'id')::uuid;if (public.community_api('exchange','POST',body)->>'id')::uuid<>item then raise exception 'Listing replay failed';end if;
 perform set_config('request.jwt.claim.sub',v::text,true);conv:=(public.community_api('exchange/'||item||'/action','POST','{"action":"enquire"}')->>'id')::uuid;perform public.community_api('exchange/'||item||'/action','POST','{"action":"save"}');
 body:=jsonb_build_object('body','TEST enquiry','key',gen_random_uuid());perform public.community_api('exchange/conversations/'||conv,'POST',body);perform public.community_api('exchange/conversations/'||conv,'POST',body);if jsonb_array_length(public.community_api('exchange/conversations/'||conv))<>1 then raise exception 'Message replay failed';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);bad:=false;begin perform public.community_api('exchange/conversations/'||conv);exception when others then bad:=true;end;if not bad then raise exception 'Enquiry leaked';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 home:=(public.community_api('homes','POST',jsonb_build_object('key',gen_random_uuid(),'flatId',flat,'purpose','rent','title','TEST 2 BHK','description','TEST home','bhk',2,'area',1200,'floor',2,'furnishing','Semi furnished','parking',1,'available',current_date,'price',2000000,'deposit',4000000,'photos','[]'::jsonb))->>'id')::uuid;
 perform public.community_api('homes/'||home||'/action','POST','{"action":"contact","contact":"1234567890","consent":true}');
 perform set_config('request.jwt.claim.sub',v::text,true);perform public.community_api('homes/'||home||'/action','POST','{"action":"interest"}');res:=public.community_api('homes/'||home);if res->>'contact'<>'' or res ? 'flat_id' then raise exception 'Home phone/address leak';end if;select id into hi from public.home_interests where listing_id=home and user_id=v;
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.community_api('homes/'||home||'/action','POST',jsonb_build_object('action','accept','requestId',hi));
 perform set_config('request.jwt.claim.sub',v::text,true);if public.community_api('homes/'||home)->>'contact'<>'1234567890' then raise exception 'Accepted home contact missing';end if;perform public.community_api('homes/'||home||'/action','POST','{"action":"withdraw"}');if public.community_api('homes/'||home)->>'contact'<>'' then raise exception 'Home phone revoke failed';end if;
 -- Restore a ride connection, then block: the accepted seat must be released.
 perform public.community_api('rides/'||ride,'PATCH','{"action":"request"}');
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.community_api('rides/'||ride,'PATCH',jsonb_build_object('action','accept','requestId',rid));
 perform set_config('request.jwt.claim.sub',v::text,true);
 perform public.community_api('blocks/'||u,'POST','{}');
